const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
const mongoose = require('mongoose');

const SCHOOL_ID = new mongoose.Types.ObjectId('69ce960a98ca4ee738d25416');
const CREATED_BY = new mongoose.Types.ObjectId('69ce960b98ca4ee738d25432');

let blockNum = 0;
function bid() { return 'block-' + String(++blockNum).padStart(3, '0'); }

function t(order, content) {
  return { blockId: bid(), type: 'text', order, content, points: 0, hints: [], explanation: '', metadata: {}, curriculumNodeId: null, cognitiveLevel: null };
}
function q(order, question, options, correctIndex, explanation, hints) {
  return {
    blockId: bid(), type: 'quiz', order,
    content: JSON.stringify({ question, options, correctIndex }),
    points: 1, hints: hints || [], explanation: explanation || '',
    metadata: { options, correctIndex }, curriculumNodeId: null, cognitiveLevel: null,
  };
}
function fb(order, text, blanks, explanation, hints) {
  return {
    blockId: bid(), type: 'fill_blank', order,
    content: JSON.stringify({ text, blanks }),
    points: blanks.length, hints: hints || [], explanation: explanation || '',
    metadata: { blanks }, curriculumNodeId: null, cognitiveLevel: null,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 1: The Design Process and Mechanical Systems (Term 1)
// ═══════════════════════════════════════════════════════════════════════════════

// Lesson 1.1: Introduction to the Design Process (IDMEC)
blockNum = 0;
const ch1_lesson1 = [
  t(1, "## What Is Technology?\n\n**Technology** is the use of knowledge, skills, and resources to design and make products that solve problems and satisfy human needs and wants.\n\nTechnology is not just about computers and phones — it includes every tool, structure, and system that humans have created to improve their lives.\n\n### Technology in Everyday Life\n\n| Item | Problem It Solves |\n|------|-------------------|\n| Pencil | Need to record information |\n| Umbrella | Need to stay dry in rain |\n| Wheelchair | Need for mobility |\n| Water tank (JoJo tank) | Need to store rainwater |\n| Solar panel | Need for electricity without power lines |\n\n### Technology in South Africa\n\nSouth Africa has a long history of technology — from ancient iron smelting in Limpopo over 1 800 years ago to modern innovations like the CAT scan (invented by South African-born Allan Cormack). Technology education helps you become a problem-solver who can improve your community."),
  t(2, "## The Design Process — IDMEC\n\nIn Technology, you follow a step-by-step method called the **IDMEC design process** when you design and make a product.\n\n### The Five Steps of IDMEC\n\n| Step | Name | What You Do |\n|------|------|------------|\n| **I** | **Investigate** | Research the problem. Find out who needs a solution, what exists already, and what the requirements are. |\n| **D** | **Design** | Write a design brief, list specifications and constraints, and sketch at least two possible ideas. |\n| **M** | **Make** | Plan the steps (flow chart), gather tools and materials, and build your solution safely. |\n| **E** | **Evaluate** | Test your product against the specifications. Does it work? Is it strong? Does it look good? What could be improved? |\n| **C** | **Communicate** | Present your work — show sketches, working drawings, the model, and explain your design decisions. |\n\n### Key Vocabulary\n\n| Term | Meaning |\n|------|--------|\n| **Design brief** | A short statement describing what you will design and make |\n| **Specifications** | Requirements the solution must meet (e.g. must hold 500 g, must be waterproof) |\n| **Constraints** | Limitations you must work within (e.g. budget of R30, maximum size 20 cm, 3 weeks to complete) |"),
  q(3, 'What does the letter "D" stand for in the IDMEC design process?',
    ['Design', 'Develop', 'Discover', 'Demonstrate'], 0,
    'IDMEC stands for Investigate, Design, Make, Evaluate, Communicate. The "D" step is where you write a design brief, list specifications and constraints, and sketch your ideas.'),
  t(4, "## The Investigate Step in Detail\n\nThe first step of IDMEC is to **investigate** the problem thoroughly before you start designing.\n\n### What to Investigate\n\n1. **The problem or scenario** — Read it carefully. Who has the problem? What do they need?\n2. **Existing products** — Look at products that already solve a similar problem. What works well? What doesn't?\n3. **Materials available** — What materials can you use? What are their properties?\n4. **User needs** — Who will use the product? What are their requirements?\n\n### Analysing Existing Products\n\nWhen investigating an existing product, consider these factors:\n\n| Factor | Questions to Ask |\n|--------|------------------|\n| **Fitness for purpose** | Does it do what it is supposed to do? |\n| **Safety** | Is it safe to use? Are there sharp edges or toxic materials? |\n| **Cost** | Is it affordable? Is it good value for money? |\n| **Aesthetics** | Does it look attractive? Is the finish good? |\n| **Ergonomics** | Is it comfortable and easy to use? Does it fit the human body? |\n| **Durability** | Will it last a long time without breaking? |\n| **Environmental impact** | Is it recyclable? Does it cause pollution? |\n\n### South African Scenario Example\n\n> *A school in Limpopo needs a device to rescue small animals that have fallen into open drains on the school property. The device must be lightweight, easy for learners to use, and made from locally available materials.*"),
  fb(5, 'The five steps of the IDMEC design process are Investigate, ___, Make, Evaluate, and ___.',
    ['Design', 'Communicate'],
    'IDMEC: Investigate, Design, Make, Evaluate, Communicate. You investigate the problem first, then design a solution, make it, evaluate it, and finally communicate your findings.'),
  t(6, "## The Design Step — Specifications and Constraints\n\n### Writing a Design Brief\n\nA **design brief** is a short paragraph that states:\n- **What** you will design and make\n- **Who** it is for\n- **What** it must do\n\n**Example:** *Design and make a rescue device for lifting small animals out of open drains. It must be lightweight, easy to use, and made from found materials.*\n\n### Specifications vs Constraints\n\n| | Specifications | Constraints |\n|--|---------------|-------------|\n| **What they are** | Things the product MUST do | Things that LIMIT your design |\n| **Examples** | Must support 2 kg, must be waterproof, must fold flat | Budget of R30, size under 30 cm, 2 weeks to complete |\n\n### Sketching Design Ideas\n\nYou must draw at least **two different design ideas** as freehand 3D sketches:\n- Label each sketch with materials, dimensions, and features\n- Use pencil for sketching (not pen)\n- Show the product from an angle that reveals its shape\n- Add notes explaining how it works\n\n### Choosing the Best Design\n\nUse an **evaluation matrix** — a table that scores each idea against the specifications:\n\n| Criteria | Idea 1 (Score /5) | Idea 2 (Score /5) |\n|----------|-------------------|-------------------|\n| Strength | 4 | 3 |\n| Cost | 5 | 4 |\n| Ease of use | 3 | 5 |\n| **Total** | **12** | **12** |"),
  q(7, 'What is the difference between specifications and constraints in a design brief?',
    ['Specifications are requirements to meet; constraints are limitations to work within', 'They mean the same thing', 'Specifications are for size; constraints are for cost only', 'Constraints are more important than specifications'], 0,
    'Specifications are the must-have requirements (e.g. must hold 2 kg). Constraints are the limitations you must work within (e.g. budget, time, size). Both are essential for a good design brief.'),
  t(8, "## Make, Evaluate, and Communicate\n\n### Make\n\n1. Create a **flow chart** showing the steps of construction in order\n2. List all **tools and materials** needed\n3. Follow **safe working practices** at all times\n4. Build the product neatly, following your chosen design\n\n### Safe Working Practices\n\n| Rule | Reason |\n|------|--------|\n| Wear safety goggles when cutting | Protects eyes from flying pieces |\n| Clamp work securely before cutting | Stops material from slipping |\n| Cut away from your body | Prevents cuts if the tool slips |\n| Keep your workspace tidy | Prevents tripping and losing tools |\n| Use the right tool for the job | Wrong tools cause injury and poor results |\n\n### Evaluate\n\nTest your product against each specification:\n- Does it meet the requirements?\n- What are its strengths?\n- What could be improved?\n- Would you change anything if you made it again?\n\n### Communicate\n\nPresent your project by showing:\n- Your design sketches and final drawings\n- The physical product or model\n- A short explanation of your design decisions\n- What you would improve next time"),
  fb(9, 'When cutting materials, you should always clamp the work ___ and cut ___ from your body for safety.',
    ['securely', 'away'],
    'Clamping prevents the material from slipping while cutting. Cutting away from your body ensures that if the tool slips, it moves in a safe direction.'),
  q(10, 'Which of the following is an example of a constraint in a design brief?',
    ['A budget limit of R50', 'The product must be waterproof', 'The product must hold 5 kg', 'The product must be red'], 0,
    'A budget of R50 is a constraint — it limits what you can spend. The other options are specifications (requirements the product must meet). Constraints include budget, time, available materials, and size limits.'),
];

// Lesson 1.2: Simple Mechanisms — Levers and Hydraulics
blockNum = 0;
const ch1_lesson2 = [
  t(1, "## What Is a Mechanism?\n\nA **mechanism** is a device that changes an input force or motion into a different output force or motion. Mechanisms are the building blocks of all machines.\n\n### Input → Process → Output\n\nEvery mechanism can be described as a system:\n\n| Part | Description | Example (scissors) |\n|------|-------------|--------------------|\n| **Input** | The force or motion you apply | Your hand squeezes the handles |\n| **Process** | How the mechanism changes the force/motion | The pivot and blades act as levers |\n| **Output** | The useful result | Paper is cut |\n\n### Types of Mechanisms\n\nAt Grade 7 level, you will learn about:\n- **Levers** (three classes)\n- **Linkages** (changing direction of motion)\n- **Hydraulic and pneumatic systems** (using liquids and gases to transmit force)"),
  t(2, "## Levers — The Simplest Mechanism\n\nA **lever** is a rigid bar that turns around a fixed point called the **fulcrum** (or pivot).\n\n### Parts of a Lever\n\n- **Fulcrum (pivot):** The fixed point around which the lever turns\n- **Effort:** The force you apply to the lever\n- **Load:** The force the lever is working against (the weight being lifted or moved)\n\n### Three Classes of Levers\n\n| Class | Arrangement | Example |\n|-------|------------|--------|\n| **Class 1** | Fulcrum is **between** effort and load | Seesaw, scissors, pliers, crowbar |\n| **Class 2** | Load is **between** effort and fulcrum | Wheelbarrow, nutcracker, bottle opener |\n| **Class 3** | Effort is **between** load and fulcrum | Tweezers, fishing rod, human forearm |\n\n### Memory Trick\n\nThink of the letters **F-L-E** (Fulcrum, Load, Effort):\n- **Class 1:** **F** in the middle → **F**-ulcrum between Load and Effort\n- **Class 2:** **L** in the middle → **L**-oad between Fulcrum and Effort\n- **Class 3:** **E** in the middle → **E**-ffort between Fulcrum and Load"),
  q(3, 'A wheelbarrow is an example of which class of lever?',
    ['Class 2', 'Class 1', 'Class 3', 'Not a lever'], 0,
    'A wheelbarrow is a class 2 lever — the wheel is the fulcrum, the load (soil, bricks) is in the middle, and you push up on the handles (effort) at the end. The load is between the fulcrum and the effort.'),
  t(4, "## Mechanical Advantage\n\n**Mechanical advantage (MA)** tells you how much a lever multiplies your effort force.\n\n$$\\text{MA} = \\frac{\\text{Load}}{\\text{Effort}}$$\n\n### What the Number Means\n\n| MA Value | Meaning | Example |\n|----------|--------|--------|\n| MA > 1 | The lever **multiplies force** — you apply less effort than the load | Crowbar (MA = 5 means you push with 100 N to lift 500 N) |\n| MA = 1 | No multiplication — effort equals the load | A balanced seesaw |\n| MA < 1 | The lever **multiplies speed/distance** but needs more effort | Tweezers, fishing rod |\n\n### Example Calculation\n\nA learner uses a crowbar to lift a 400 N rock. She applies an effort of 100 N.\n\n$$\\text{MA} = \\frac{400}{100} = 4$$\n\nThe crowbar multiplies her force **4 times**.\n\n### The Trade-Off\n\nWhen you gain force, you lose distance. If a lever multiplies force by 4, the effort end must move **4 times further** than the load end. You cannot get something for nothing — this is a fundamental rule in all mechanisms."),
  fb(5, 'Mechanical advantage is calculated by dividing the ___ by the ___. In a class 1 lever, the ___ is between the effort and the load.',
    ['load', 'effort', 'fulcrum'],
    'MA = Load ÷ Effort. In a class 1 lever, the fulcrum sits between the effort and the load — like a seesaw where the pivot is in the centre.'),
  t(6, "## Hydraulic and Pneumatic Systems\n\nSome mechanisms use **fluids** (liquids or gases) instead of rigid bars to transmit force.\n\n### Hydraulic Systems (Liquids)\n\nA **hydraulic system** uses a liquid (usually oil or water) inside tubes and cylinders to transmit force.\n\n| Feature | Detail |\n|---------|--------|\n| **Fluid used** | Oil or water (liquids cannot be compressed) |\n| **How it works** | Pushing a small piston creates pressure in the liquid, which pushes a larger piston with more force |\n| **Advantage** | Can multiply force greatly |\n| **South African examples** | Car brakes, hydraulic jacks, excavators on construction sites, the hydraulic lifts at Sasol refineries |\n\n### Pneumatic Systems (Gases)\n\nA **pneumatic system** uses compressed air (gas) to transmit force.\n\n| Feature | Detail |\n|---------|--------|\n| **Fluid used** | Air or other gas (gases CAN be compressed) |\n| **How it works** | Compressed air pushes a piston to create movement |\n| **Advantage** | Fast, clean, and safe |\n| **South African examples** | Pneumatic drills on roads, air brakes on trucks, dental drills, inflating tyres |\n\n### Key Difference\n\n| Property | Hydraulic (Liquid) | Pneumatic (Gas) |\n|----------|-------------------|----------------|\n| Can be compressed? | **No** — liquid is incompressible | **Yes** — gas can be squeezed smaller |\n| Force transfer | Smooth and precise | Slightly springy (because gas compresses) |\n| Speed | Slower | Faster |"),
  q(7, 'What is the key difference between a hydraulic system and a pneumatic system?',
    ['Hydraulic uses liquid (incompressible); pneumatic uses gas (compressible)', 'Hydraulic uses gas; pneumatic uses liquid', 'They are exactly the same', 'Hydraulic is faster than pneumatic'], 0,
    'Hydraulic systems use liquid (oil or water) which cannot be compressed, giving precise force transfer. Pneumatic systems use air or gas, which can be compressed, making them faster but slightly less precise.'),
  t(8, "## Practical Investigation: Syringes as Hydraulic Systems\n\nYou can investigate how hydraulic systems work using plastic syringes and water.\n\n### Equipment\n\n- 2 plastic syringes (one small, one large)\n- Plastic tubing to connect them\n- Water\n\n### Method\n\n1. Fill the system with water (no air bubbles)\n2. Push the small syringe plunger in → the large syringe plunger pushes out\n3. Try pushing the large syringe in → the small syringe pushes out further but with less force\n\n### What You Observe\n\n| Input Syringe | Output Syringe | Force | Distance |\n|--------------|----------------|-------|----------|\n| Small (push in) | Large (pushes out) | **More force** at output | **Less distance** at output |\n| Large (push in) | Small (pushes out) | **Less force** at output | **More distance** at output |\n\n### Explanation\n\nThe pressure in the liquid is the same everywhere. A large piston has more area for the pressure to push on, so it produces more force. But it moves less distance because the same volume of liquid spreads over a larger area.\n\n### Comparing to Levers\n\nHydraulic systems follow the same trade-off as levers:\n- **Gain force → lose distance**\n- **Gain distance → lose force**\n- You can never get more energy out than you put in"),
  fb(9, 'In a hydraulic system, liquid is ___ (it cannot be squeezed smaller). When a small syringe pushes liquid into a large syringe, the output force is ___ than the input force.',
    ['incompressible', 'greater'],
    'Liquids are incompressible — they transmit pressure equally in all directions. A larger output piston has more area, so the same pressure creates a greater force (but less distance).'),
  q(10, 'Which South African application uses a pneumatic system?',
    ['Pneumatic drills used for roadwork', 'Car brakes', 'Hydraulic jacks', 'Dam sluice gates'], 0,
    'Pneumatic drills use compressed air to break up road surfaces. Car brakes and hydraulic jacks use hydraulic (liquid) systems. Pneumatic systems are common on South African road construction sites.'),
];

